def ollama_generate(model: str, prompt: str, *, timeout: int = 120) -> str:
    """Call local Ollama model for hypothesis generation."""
    try:
        result = subprocess.run(
            ["ollama", "run", model],
            input=prompt,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        if result.returncode != 0:
            print(f"[ollama] {model} error: {result.stderr[:200]}", file=sys.stderr)
            return ""
        return result.stdout.strip()
    except subprocess.TimeoutExpired:
        print(f"[ollama] {model} timed out after {timeout}s", file=sys.stderr)
        return ""
    except FileNotFoundError:
        print("[ollama] not installed — falling back to manual mode", file=sys.stderr)
        return ""

