def ollama_generate(model: str, prompt: str, *, timeout: int = 600) -> str:
    """Call local Ollama model via HTTP API for hypothesis generation."""
    import urllib.request
    import urllib.error

    url = "http://localhost:11434/api/generate"
    payload = json.dumps({
        "model": model,
        "prompt": prompt,
        "stream": False,
        "options": {"num_predict": 4096, "temperature": 0.7},
    }).encode()

    req = urllib.request.Request(
        url, data=payload,
        headers={"Content-Type": "application/json"},
    )
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            data = json.loads(resp.read().decode())
            return data.get("response", "").strip()
    except urllib.error.URLError as e:
        print(f"[ollama] HTTP error: {e}", file=sys.stderr)
        return ""
    except TimeoutError:
        print(f"[ollama] {model} timed out after {timeout}s", file=sys.stderr)
        return ""
    except Exception as e:
        print(f"[ollama] unexpected error: {e}", file=sys.stderr)
        return ""

